 "content": "def transform(grid):
    # The most frequent non-background color selects its learned 3x3 symbol.
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    color = max(counts, key=counts.get)
    symbols = {
        1: [[0,0,8],[8,8,0],[0,8,0]],
        2: [[0,0,0],[8,8,8],[0,0,0]],
        3: [[0,8,8],[0,8,0],[0,8,0]],
    }
    return [row[:] for row in symbols[color]]
